recommendations.command:
kubectl patch configmap coredns -n kube-system --type merge -p '{"data":{"Corefile":".:53 {
    errors
    health
    ready
    kubernetes cluster.local in-addr.arpa ip6.arpa {
        pods insecure
        fallthrough in-addr.arpa ip6.arpa
    }
    prometheus :9153
    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}
azurecr.io:53 {
    forward 168.63.129.16
    cache 30
}
"}}'
